function absolute_value(value: int64) returns int64:
    if value < 0:
        return -value
    return value

function signed_gcd(a: int64, b: int64) returns int64:
    mutable int64 x = absolute_value(a)
    mutable int64 y = absolute_value(b)
    while y != 0:
        mutable int64 remainder = x modulo y
        x = y
        y = remainder
    return x

